package com.company.tpm.telegram;import com.company.tpm.employee.Employee;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="telegram_links")public class TelegramLink{@Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@OneToOne(optional=false,fetch=FetchType.LAZY)private Employee employee;@Column(nullable=false,unique=true)private long telegramUserId;@Column(nullable=false)private long telegramChatId;@Column(nullable=false)private Instant linkedAt=Instant.now();@Column(nullable=false)private boolean active=true;protected TelegramLink(){}public TelegramLink(Employee e,long user,long chat){employee=e;telegramUserId=user;telegramChatId=chat;}public Employee getEmployee(){return employee;}public long getTelegramChatId(){return telegramChatId;}public void disconnect(){active=false;}}
